//! The worn layers of the registered armor: which texture each material gives each layer, from the original's material render
//! info and the pre-baked `tinker_armor` textures (SlimeKnights, MIT; see LICENSE). Generated by tools/import_original_data.py;
//! `armor_worn.rs` reads it. A base absent from BASES is a layer the original skips for that layer set.

/// One layer of an armor model: a base texture, or the texture of the material in a tool slot.
pub(crate) enum Layer {
    Fixed(&'static str),
    Material(&'static str, usize),
}

/// Item path -> (family, layer-set word `armor`, `leggings` or `wings`).
pub(crate) const ITEMS: &[(&str, &str, &str)] = &[
    ("plate_boots", "plate", "armor"),
    ("plate_chestplate", "plate", "armor"),
    ("plate_helmet", "plate", "armor"),
    ("plate_leggings", "plate", "leggings"),
    ("slime_boots", "slime", "armor"),
    ("slime_chestplate", "slime", "armor"),
    ("slime_leggings", "slime", "leggings"),
    ("slime_wings", "slime_wings", "wings"),
    ("travelers_boots", "travelers", "armor"),
    ("travelers_chestplate", "travelers", "armor"),
    ("travelers_helmet", "travelers", "armor"),
    ("travelers_leggings", "travelers", "leggings"),
];

/// The layers of each family, in draw order; each prefix is completed with the layer-set word.
pub(crate) const FAMILIES: &[(&str, &[Layer])] = &[
    ("travelers", &[Layer::Fixed("travelers/base_"), Layer::Material("travelers/cuirass_", 1), Layer::Material("travelers/metal_", 0)]),
    ("plate", &[Layer::Material("plate/plating_", 0), Layer::Material("plate/maille_", 1)]),
    ("slime", &[Layer::Material("slime/", 1), Layer::Material("slime/overlay_", 0)]),
    ("slime_wings", &[Layer::Material("slime/", 0)]),
];

/// Every base texture the original ships (a path under the layer set's texture folder, without `.png`), sorted.
pub(crate) const BASES: &[&str] = &[
    "plate/maille_armor",
    "plate/maille_leggings",
    "plate/plating_armor",
    "plate/plating_leggings",
    "slime/armor",
    "slime/leggings",
    "slime/overlay_armor",
    "slime/overlay_leggings",
    "slime/wings",
    "travelers/base_armor",
    "travelers/cuirass_armor",
    "travelers/cuirass_leggings",
    "travelers/metal_armor",
    "travelers/metal_leggings",
];

